"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97411"],{43830(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cascata_destino_desconhecido","status":422,"titulo":"A cascata declara destino que n\xe3o \xe9 modalidade selecionada em nenhuma oferta do processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cascata_destino_desconhecido","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["A cascata do processo declara, como destino de alguma origem, um c\xf3digo\\nde modalidade que n\xe3o \xe9 modalidade selecionada em nenhuma oferta do\\nprocesso \u2014 nem na oferta espec\xedfica onde a origem `SEGUE_ORDEM_DE_REMANEJAMENTO` est\xe1\\n(coberto por\\n[`cascata_fallback_nao_selecionado_na_oferta`](/erros/uniplus.selecao.processo_seletivo.cascata_fallback_nao_selecionado_na_oferta),\\nquando \xe9 o \xfanico destino que resolveria ali), nem em oferta nenhuma. Um\\ndestino que n\xe3o existe em lugar algum do processo \xe9 sempre um destino\\nmorto, mesmo que outra posi\xe7\xe3o da mesma fila resolva numa oferta\\nespec\xedfica.","\xc9 avaliada na mesma passada, sobre o conjunto do processo, de\\n[`cascata_origem_nao_segue_cascata`](/erros/uniplus.selecao.processo_seletivo.cascata_origem_nao_segue_cascata)\\n\u2014 por origem, em ordem determin\xedstica, e para cada origem, por destino,\\ntamb\xe9m em ordem. Cada destino com essa inconsist\xeancia gera uma causa, e as causas se acumulam em\\n`errors[]`, com as demais desta s\xe9rie. A mensagem diz que a cascata declara um destino que n\xe3o \xe9\\nmodalidade selecionada em nenhuma oferta do processo, sem trazer o c\xf3digo do destino."],"comoResolver":["Como a mensagem n\xe3o traz o c\xf3digo do destino, confira os destinos da cascata e corrija o c\xf3digo que n\xe3o corresponde a modalidade ofertada, para uma modalidade que de fato est\xe1\\nselecionada em alguma oferta do processo, ou remova a posi\xe7\xe3o da fila se\\nela n\xe3o corresponde a nenhuma modalidade real."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);